export interface WaysBackAdjustment {
  /** The Sunday of the week it lowers */
  weekStart: string;
  /** Whole cents, negative */
  amountCents: number;
  /** @nullable */
  reason: string | null;
}

export interface WaysBackTrim {
  categoryId: string;
  name: string;
  /** This week's spend in the category, whole cents: (S6) purchases less refunds, as the week's spent figure and the period breakdown's category amount net them. Always > 0 (a fully refunded category is not a trim). */
  spentWeek: number;
  /**
   * Median weekly spend in the category over the 8 weeks before this one (a week with none counts as 0; weeks before tracking began are left out), whole cents, refunds netted the same way; null when no week counts. (F3) Each week read only to today's weekday (Sunday through usualThrough's weekday): the usual by today.
   * @nullable
   */
  usualWeek: number | null;
  /**
   * (F3) The same median over the whole 8 weeks, whole cents; null when no week counts
   * @nullable
   */
  usualFullWeek: number | null;
}

export type WaysBackHold = {
  /** @nullable */
  perDay: number | null;
  /** @nullable */
  leavesUntilPayday: number | null;
};

/**
 * (F3) Each trim's usualWeek reads the prior weeks to the same weekday
 */
export type WaysBackUsualBasis =
  (typeof WaysBackUsualBasis)[keyof typeof WaysBackUsualBasis];

export const WaysBackUsualBasis = {
  same_days: "same_days",
} as const;

export type WaysBackCarryOver = {
  nextWeekStart: string;
  /** @nullable */
  nextWeekCap: number | null;
  /** The household already chose a carry-over for next week */
  applied: boolean;
  adjustment: WaysBackAdjustment | null;
};

/**
 * (V5) A way back when the week is over. Every amount is WHOLE CENTS. overBy = max(0, −remainingWeek). hold.perDay = floor(max(0, remainingWeek) ÷ daysLeft), null with no cap; hold.leavesUntilPayday = availableUntilPayday (null with no bank data). trims = the three categories that spent most this week among the rows counting against the cap. carryOver.nextWeekCap = max(0, next week's cap + the applied adjustment, or − overBy when none is applied); null with no cap.
 */
export interface WaysBack {
  weekStart: string;
  weekEnd: string;
  /**
   * How far past the cap this week is, whole cents; 0 when not over
   * @minimum 0
   */
  overBy: number;
  /**
   * Days left in the week, today included
   * @minimum 1
   * @maximum 7
   */
  daysLeft: number;
  hold: WaysBackHold;
  trims: WaysBackTrim[];
  /** (F3) Each trim's usualWeek reads the prior weeks to the same weekday */
  usualBasis: WaysBackUsualBasis;
  /** (F3) Today (YYYY-MM-DD): each prior week is cut at its weekday */
  usualThrough: string;
  carryOver: WaysBackCarryOver;
}

