export type TransactionSplitsPropertyItem = {
  categoryId: string;
  amount: string;
};

/**
 * (PR-D) A payment logged in the app (POST /debts/{id}/payments) is
a claim: "claimed" when written, "confirmed" once a bank row pairs
with it. Null on every other row.

 * @nullable
 */
export type TransactionPaymentState =
  | (typeof TransactionPaymentState)[keyof typeof TransactionPaymentState]
  | null;

export const TransactionPaymentState = {
  claimed: "claimed",
  confirmed: "confirmed",
} as const;

export interface Transaction {
  id: string;
  occurredOn: string;
  /** @nullable */
  occurredAt?: string | null;
  description: string;
  amount: string;
  /** @nullable */
  account?: string | null;
  /** @nullable */
  categoryId?: string | null;
  forecastFlag: boolean;
  weeklyAllowance: boolean;
  /** @nullable */
  weeklyBucket?: TransactionWeeklyBucket;
  monthlyAllowance: boolean;
  unplannedAllowance: boolean;
  reimbursable: boolean;
  reimbursed: boolean;
  /** Whether the user has marked this transaction as done on the
Amex page. Reviewed rows render greyed out so the eye skips
over them and focuses on what's left to handle. Defaults to
false; toggled explicitly by the user (never auto-set on
categorize).
 */
  reviewed: boolean;
  isTransfer: boolean;
  /** True when the user has explicitly toggled `isTransfer` on this
row (cleared the auto-flag from the row's "Transfer" pill, picked
a real category on a transfer row, or flipped the toggle in the
Edit dialog). The Plaid sync / XLSX import re-categorize
paths honor this and skip the description/PFC
transfer heuristic so future syncs of the same row don't
silently re-flag it as a transfer. Server-managed: writes to
this field are not accepted via the input schema — toggling
`isTransfer` in PATCH /transactions/:id sets it automatically.
 */
  isTransferUserOverridden: boolean;
  /** (PR-0) True when a person chose this row's category by hand:
PATCH /transactions/:id or bulk-update with a categoryId,
recategorize-by-pattern, or a create whose body named the
category (never a mapping rule's auto-fill). Clearing the
category (categoryId null, uncategorize-by-ids) clears it. The
automatic categorizer never moves a locked row and Plaid sync
never writes it. Server-managed and read-only: the input schemas
do not accept it.
 */
  readonly categoryLockedByUser?: boolean;
  /** (F4b) The parts of a VALID category split, on `GET /transactions`
list rows only: each part's category and amount (same string
format and sign as `amount`; the parts add up to `amount` to the
cent). Omitted for a charge with no split and for one whose split
is invalid or does not add up; such a charge counts whole under
its own category, as the server's category totals do.
 */
  readonly splits?: readonly TransactionSplitsPropertyItem[];
  /** (#632 follow-up) User-set per-row flag marking a card payment
as going to a card that is NOT in our debt avalanche (e.g. a
spouse's external card). Excluded from avalanche actuals so
it never inflates "extra" debt-payoff capacity. Defaults to
false; toggled explicitly via the "Not in avalanche" chip on
the Amex page.
 */
  isExternalCardPayment: boolean;
  /**
   * (#762 — Phase B) ISO8601 timestamp the user clicked "Send
to Review" on this row, or null when the row has never been
promoted into the Review workflow. The Chase / Amex
source-of-truth views ignore this column entirely; only the
Review pipeline on /forecast filters on it. Drives the "✓
in review" badge and per-row affordance on the Chase page.

   * @nullable
   */
  sentToReviewAt?: string | null;
  /** @nullable */
  notes?: string | null;
  source: string;
  /** @nullable */
  member?: string | null;
  /** @nullable */
  owedBy?: string | null;
  /** @nullable */
  plaidTransactionId?: string | null;
  /** @nullable */
  plaidAccountId?: string | null;
  /** @nullable */
  debtId?: string | null;
  /**
   * Plaid personal_finance_category.detailed, persisted on sync (#636); null for manual and imported rows. Read by the one spending rule (classifyOutflow, rule 8), which the web shares.
   * @nullable
   */
  pfcDetailed?: string | null;
  /** (#728) True when Plaid reported this transaction as pending
on the most recent /transactions/sync. Replaces the legacy
`notes='[pending]'` string marker the sync used to write.
Drives the Transactions page "Pending" section (pending
rows pinned above the dated day-groups) and the "Pending"
badge on each row. Flips back to false on the
pending→posted lifecycle when Plaid surfaces the posted
twin as a `modified` row.
 */
  pending: boolean;
  /**
   * Id of the mapping rule that auto-categorize would currently
attribute for this row, or null when no rule matches (e.g. the
category was set manually). Computed server-side per list
response — not persisted on the row — so editing a rule's
pattern reflects on every existing transaction without a
backfill. Powers the "matched by rule X · jump to it" affordance
on the Transactions and Amex pages.

   * @nullable
   */
  matchedRuleId?: string | null;
  /** (#868) Clean, human-readable merchant label derived from the
raw bank `description` on read. (#888) Precedence: a household
merchant alias keyed on `merchantSignature` wins; otherwise the
deterministic `cleanMerchant()` label (ACH noise, ORIG CO / WEB
ID fields, and processor prefixes stripped). Used as the row
headline so the raw description can be demoted to a muted
sub-line. Computed server-side per list response — never
persisted; the stored `description` is untouched.
 */
  displayName?: string;
  /** (#888) Stable, normalized merchant key derived from the raw
`description`. Rows that differ only by volatile trailing IDs /
trace numbers / dates share a signature, so one rename applies to
all of them. Used by the rename popover to set/clear an alias and
to count how many rows a rename will affect. Empty string when no
stable signature can be derived. Computed server-side per list
response — never persisted.
 */
  merchantSignature?: string;
  /**
   * (PR-D) A payment logged in the app (POST /debts/{id}/payments) is
a claim: "claimed" when written, "confirmed" once a bank row pairs
with it. Null on every other row.

   * @nullable
   */
  paymentState?: TransactionPaymentState;
  /**
   * (PR-D) The bank row that confirmed this claim.
   * @nullable
   */
  confirmedByTxnId?: string | null;
}

export type LedgerRow = Transaction & {
  /** (PR-A2) How many parts the charge is split into; 0 when it is not split. */
  splitCount: number;
  /** (PR-A2) The category was set by the automatic categorizer with
middling confidence and awaits a person's yes. A hand pick clears it.
 */
  categoryProvisional: boolean;
  /**
   * (PR13) The account balance straight after this row, on the
register of all the account's rows. Null without a bank
snapshot, and for a row dated after today.

   * @nullable
   */
  runningBalance: string | null;
  /**
   * What this row moves the register by: its amount, or 0.00 when it
does not count. `totals` sum these. (PR14) Null on an account
other than the snapshot's, which has no register; there
`countsInBalance` still says whether the row counts in the totals.

   * @nullable
   */
  balanceAmount: string | null;
  /** Whether this row moves the balance at all. */
  countsInBalance: boolean;
  /** counted (moves the balance by its amount); superseded (a pending
row its posted row replaced); duplicate (a second row with the
same Plaid transaction id); not_bank (a mask-twin row, which the
bank balance does not read); claim_confirmed (PR-D: a payment
logged in the app that a bank row confirmed — the bank row is
the payment).
 */
  balanceReason: string;
  /**
   * For a posted row that replaced a pending row, that pending row's id.
   * @nullable
   */
  replacedPendingId: string | null;
  /** Dated after the snapshot day but already inside the snapshot
balance. The days between the snapshot and this row's date read
higher than the bank showed, by this row.
 */
  heldAhead: boolean;
  /** Dated after the household's today. Such a row has no running balance. */
  afterToday: boolean;
  /** Still pending and dated more than 14 days before the household's
today. A label only: the row moves the balance as balanceReason
says. A leftover pending row its posted row could not replace
counts beside that posted row.
 */
  stalePending: boolean;
};

